describe('Restore Archived Record', () => {
  const baseUrl = Cypress.env('BASE_URL') || 'http://localhost:3000';
  const testUser = {
    email: 'testuser@example.com',
    password: 'TestPassword123!'
  };

  beforeEach(() => {
    cy.visit(`${baseUrl}/login`);
    cy.get('input[name="email"]').type(testUser.email);
    cy.get('input[name="password"]').type(testUser.password);
    cy.get('button[type="submit"]').click();
    cy.url().should('include', '/dashboard');
    cy.wait(500);
  });

  it('should successfully restore an archived record', () => {
    cy.visit(`${baseUrl}/records`);
    cy.get('[data-testid="filter-status"]').click();
    cy.get('[data-testid="filter-archived"]').click();
    cy.wait(500);

    cy.get('[data-testid="archived-records-list"]').should('exist');
    cy.get('[data-testid="record-item"]').first().as('firstRecord');
    cy.get('@firstRecord').should('contain', 'Archived');

    cy.get('@firstRecord').find('[data-testid="record-actions-menu"]').click();
    cy.get('[data-testid="restore-record-option"]').click();

    cy.get('[data-testid="restore-confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-restore-button"]').click();

    cy.get('[data-testid="success-toast"]').should('contain', 'Record restored successfully');
    cy.get('[data-testid="success-toast"]').should('have.class', 'toast-success');

    cy.get('[data-testid="filter-status"]').click();
    cy.get('[data-testid="filter-active"]').click();
    cy.wait(500);

    cy.get('[data-testid="records-list"]').should('exist');
    cy.get('[data-testid="record-item"]').first().should('not.contain', 'Archived');
  });

  it('should handle restore operation with network error gracefully', () => {
    cy.intercept('POST', '**/api/records/*/restore', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('restoreError');

    cy.visit(`${baseUrl}/records`);
    cy.get('[data-testid="filter-status"]').click();
    cy.get('[data-testid="filter-archived"]').click();
    cy.wait(500);

    cy.get('[data-testid="record-item"]').first().find('[data-testid="record-actions-menu"]').click();
    cy.get('[data-testid="restore-record-option"]').click();

    cy.get('[data-testid="restore-confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-restore-button"]').click();

    cy.wait('@restoreError');
    cy.get('[data-testid="error-toast"]').should('be.visible');
    cy.get('[data-testid="error-toast"]').should('contain', 'Failed to restore record');
    cy.get('[data-testid="error-toast"]').should('have.class', 'toast-error');

    cy.get('[data-testid="restore-confirmation-modal"]').should('not.exist');
  });

  it('should cancel restore operation when user clicks cancel button', () => {
    cy.visit(`${baseUrl}/records`);
    cy.get('[data-testid="filter-status"]').click();
    cy.get('[data-testid="filter-archived"]').click();
    cy.wait(500);

    cy.get('[data-testid="record-item"]').first().as('targetRecord');
    cy.get('@targetRecord').find('[data-testid="record-actions-menu"]').click();
    cy.get('[data-testid="restore-record-option"]').click();

    cy.get('[data-testid="restore-confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="cancel-restore-button"]').click();

    cy.get('[data-testid="restore-confirmation-modal"]').should('not.exist');
    cy.get('[data-testid="success-toast"]').should('not.exist');
    cy.get('[data-testid="error-toast"]').should('not.exist');

    cy.get('@targetRecord').should('contain', 'Archived');
  });

  it('should restore multiple archived records sequentially', () => {
    cy.visit(`${baseUrl}/records`);
    cy.get('[data-testid="filter-status"]').click();
    cy.get('[data-testid="filter-archived"]').click();
    cy.wait(500);

    cy.get('[data-testid="record-item"]').should('have.length.greaterThan', 1);

    cy.get('[data-testid="record-item"]').eq(0).find('[data-testid="record-actions-menu"]').click();
    cy.get('[data-testid="restore-record-option"]').click();
    cy.get('[data-testid="confirm-restore-button"]').click();
    cy.get('[data-testid="success-toast"]').should('be.visible');
    cy.wait(500);

    cy.get('[data-testid="record-item"]').eq(0).find('[data-testid="record-actions-menu"]').click();
    cy.get('[data-testid="restore-record-option"]').click();
    cy.get('[data-testid="confirm-restore-button"]').click();
    cy.get('[data-testid="success-toast"]').should('be.visible');

    cy.get('[data-testid="filter-status"]').click();
    cy.get('[data-testid="filter-active"]').click();
    cy.wait(500);

    cy.get('[data-testid="records-list"]').should('exist');
    cy.get('[data-testid="record-item"]').should('have.length.greaterThan', 1);
  });

  it('should display proper validation when attempting to restore non-existent record', () => {
    cy.intercept('POST', '**/api/records/invalid-id/restore', {
      statusCode: 404,
      body: { error: 'Record not found' }
    }).as('recordNotFound');

    cy.visit(`${baseUrl}/records/invalid-id/restore`);
    cy.wait('@recordNotFound');

    cy.get('[data-testid="error-message"]').should('contain', 'Record not found');
    cy.get('[data-testid="back-to-records-button"]').should('be.visible');
  });
});
